-- GazaWorks normalized application schema. Apply with Supabase CLI.
create extension if not exists pgcrypto;
create type public.account_type as enum ('individual','team','client');
create type public.account_status as enum ('active','suspended','banned','deletion_pending');
create type public.verification_status as enum ('draft','incomplete','ready','requested','under_review','interview_required','interview_scheduled','pending','verified','changes_requested','rejected','suspended','banned');
create type public.project_status as enum ('offer_accepted','awaiting_payment','funded','in_progress','submitted','client_review','completed','disputed','appeal','cancelled','refunded','payout_pending','paid');
create type public.message_status as enum ('delivered','pending_moderation','rejected','redacted');
create type public.payment_status as enum ('created','requires_action','authorized','captured','failed','refunded','partially_refunded');
create type public.payout_status as enum ('pending','approved','processing','paid','failed');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,account_type account_type not null,account_status account_status not null default 'active',display_name text not null check(length(display_name) between 2 and 100),avatar_path text,locale text not null default 'en',onboarding_complete boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.individual_profiles(profile_id uuid primary key references profiles(id) on delete cascade,legal_name text,professional_title text,bio text,gaza_location text,phone_private text,email_private text,availability text,years_experience smallint check(years_experience between 0 and 80),hourly_rate_minor integer check(hourly_rate_minor>=0),currency char(3),cv_path text,verification_status verification_status not null default 'draft',featured boolean not null default false);
create table public.team_profiles(profile_id uuid primary key references profiles(id) on delete cascade,team_name text not null,description text,history text,team_size integer check(team_size>0),representative_private text,gaza_location text,document_path text,rate_minor integer,currency char(3),verification_status verification_status not null default 'draft',featured boolean not null default false);
create table public.client_profiles(profile_id uuid primary key references profiles(id) on delete cascade,full_name text not null,country_code char(2) not null,company_name text,organization_type text);
create table public.team_members(id uuid primary key default gen_random_uuid(),team_id uuid not null references team_profiles(profile_id) on delete cascade,real_name_private text,public_name text,professional_title text,role text,bio text,image_path text,privacy_mode text not null check(privacy_mode in('name_image','name_only','alias','anonymous')),sort_order integer not null default 0);
create table public.categories(id uuid primary key default gen_random_uuid(),slug text unique not null,parent_id uuid references categories(id),active boolean not null default true);
create table public.category_translations(category_id uuid references categories(id) on delete cascade,locale text not null,name text not null,primary key(category_id,locale));
create table public.skills(id uuid primary key default gen_random_uuid(),slug text unique not null,active boolean not null default true);
create table public.skill_translations(skill_id uuid references skills(id) on delete cascade,locale text not null,name text not null,primary key(skill_id,locale));
create table public.profile_skills(profile_id uuid references profiles(id) on delete cascade,skill_id uuid references skills(id) on delete cascade,level smallint check(level between 1 and 5),primary key(profile_id,skill_id));
create table public.profile_details(id uuid primary key default gen_random_uuid(),profile_id uuid not null references profiles(id) on delete cascade,kind text not null check(kind in('experience','education','certification','language','tool','industry','service','achievement','project')),title text not null,organization text,description text,start_date date,end_date date,metadata jsonb not null default '{}');
create table public.portfolios(id uuid primary key default gen_random_uuid(),profile_id uuid not null references profiles(id) on delete cascade,title text not null,description text,category_id uuid references categories(id),completed_on date,created_at timestamptz not null default now());
create table public.portfolio_media(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references portfolios(id) on delete cascade,storage_path text not null,mime_type text not null,size_bytes bigint not null check(size_bytes>0),media_type text not null check(media_type in('image','video')),thumbnail_path text,sort_order integer not null default 0);
create table public.profile_drafts(id uuid primary key default gen_random_uuid(),profile_id uuid not null references profiles(id) on delete cascade,source_path text,source_kind text not null,extracted_data jsonb not null default '{}',rewrite_mode text,confirmed_at timestamptz,created_at timestamptz not null default now());
create table public.verification_requests(id uuid primary key default gen_random_uuid(),profile_id uuid not null references profiles(id),status verification_status not null default 'requested',submitted_at timestamptz not null default now(),reviewer_id uuid references profiles(id),internal_notes text,decision_reason text,decided_at timestamptz);
create table public.appointments(id uuid primary key default gen_random_uuid(),starts_at timestamptz not null,ends_at timestamptz not null,employee_id uuid references profiles(id),request_id uuid references verification_requests(id),status text not null check(status in('available','booked','blocked','cancelled','completed','no_show')),user_notes text,internal_notes text,check(ends_at>starts_at));
create table public.work_requests(id uuid primary key default gen_random_uuid(),client_id uuid not null references client_profiles(profile_id),title text not null,description text not null,category_id uuid references categories(id),budget_min_minor integer not null,budget_max_minor integer not null,currency char(3) not null,visibility text not null check(visibility in('public','invite_only')),status text not null default 'draft',delivery_expectations text,notes text,created_at timestamptz not null default now(),check(budget_max_minor>=budget_min_minor));
create table public.work_request_skills(work_request_id uuid references work_requests(id) on delete cascade,skill_id uuid references skills(id),primary key(work_request_id,skill_id));
create table public.work_request_invites(work_request_id uuid references work_requests(id) on delete cascade,profile_id uuid references profiles(id),created_at timestamptz default now(),primary key(work_request_id,profile_id));
create table public.offers(id uuid primary key default gen_random_uuid(),work_request_id uuid not null references work_requests(id),talent_id uuid not null references profiles(id),price_minor integer not null check(price_minor>0),currency char(3) not null,delivery_days integer not null check(delivery_days>0),proposal text not null,scope text not null,status text not null default 'submitted',created_at timestamptz not null default now(),unique(work_request_id,talent_id));
create table public.projects(id uuid primary key default gen_random_uuid(),work_request_id uuid references work_requests(id),client_id uuid not null references profiles(id),talent_id uuid not null references profiles(id),accepted_offer_id uuid unique references offers(id),status project_status not null default 'offer_accepted',deadline timestamptz,created_at timestamptz not null default now());
create table public.project_agreements(id uuid primary key default gen_random_uuid(),project_id uuid unique not null references projects(id),scope text not null,price_minor integer not null,currency char(3) not null,deadline timestamptz not null,accepted_at timestamptz not null,client_snapshot jsonb not null,talent_snapshot jsonb not null,offer_snapshot jsonb not null);
create table public.project_deliveries(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),message text not null,submitted_at timestamptz not null default now(),auto_accept_at timestamptz not null default(now()+interval '3 days'),accepted_at timestamptz,revision_requested_at timestamptz);
create table public.project_files(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),uploader_id uuid not null references profiles(id),delivery_id uuid references project_deliveries(id),storage_path text not null,mime_type text not null,size_bytes bigint not null,created_at timestamptz default now());
create table public.chat_rooms(id uuid primary key default gen_random_uuid(),project_id uuid references projects(id),created_at timestamptz default now());
create table public.chat_participants(room_id uuid references chat_rooms(id) on delete cascade,profile_id uuid references profiles(id),primary key(room_id,profile_id));
create table public.chat_messages(id uuid primary key default gen_random_uuid(),room_id uuid not null references chat_rooms(id),sender_id uuid not null references profiles(id),body text,message_type text not null check(message_type in('text','image','document','voice')),storage_path text,status message_status not null default 'delivered',created_at timestamptz not null default now());
create table public.message_moderation(id uuid primary key default gen_random_uuid(),message_id uuid unique not null references chat_messages(id),reason text not null,context_snapshot jsonb not null,review_deadline timestamptz not null default(now()+interval '24 hours'),reviewer_id uuid references profiles(id),decision text,redacted_body text,reviewed_at timestamptz);
create table public.transactions(id uuid primary key default gen_random_uuid(),project_id uuid unique not null references projects(id),client_id uuid not null references profiles(id),talent_id uuid not null references profiles(id),gross_minor bigint not null,platform_deduction_minor bigint not null,provider_fee_minor bigint not null,platform_revenue_minor bigint not null,worker_entitlement_minor bigint not null,currency char(3) not null,provider text not null,provider_reference text,dispute_state text not null default 'none',created_at timestamptz default now(),check(gross_minor=platform_deduction_minor+worker_entitlement_minor),check(platform_deduction_minor=provider_fee_minor+platform_revenue_minor));
create table public.payments(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references transactions(id),status payment_status not null,amount_minor bigint not null,provider_event_id text unique,simulated boolean not null default false,created_at timestamptz default now());
create table public.ledger_entries(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references transactions(id),account text not null,direction text not null check(direction in('debit','credit')),amount_minor bigint not null check(amount_minor>0),currency char(3) not null,created_at timestamptz default now());
create table public.payouts(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references transactions(id),amount_minor bigint not null,status payout_status not null default 'pending',destination_private text,transfer_reference text,payout_date date,notes text,proof_path text,approved_by uuid references profiles(id),created_at timestamptz default now());
create table public.disputes(id uuid primary key default gen_random_uuid(),project_id uuid unique not null references projects(id),opened_by uuid not null references profiles(id),reason text not null,status text not null default 'open',decision text,worker_award_minor bigint,client_refund_minor bigint,reasoning text,decided_by uuid references profiles(id),decided_at timestamptz,created_at timestamptz default now());
create table public.dispute_evidence(id uuid primary key default gen_random_uuid(),dispute_id uuid references disputes(id),submitted_by uuid references profiles(id),statement text,storage_path text,created_at timestamptz default now());
create table public.appeals(id uuid primary key default gen_random_uuid(),dispute_id uuid unique not null references disputes(id),submitted_by uuid references profiles(id),reasoning text not null,status text not null default 'open',final_decision text,decided_by uuid references profiles(id),decided_at timestamptz,created_at timestamptz default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),author_id uuid not null references profiles(id),subject_id uuid not null references profiles(id),communication smallint check(communication between 1 and 5),professionalism smallint check(professionalism between 1 and 5),overall smallint check(overall between 1 and 5),quality smallint check(quality between 1 and 5),delivery smallint check(delivery between 1 and 5),clarity smallint check(clarity between 1 and 5),cooperation smallint check(cooperation between 1 and 5),feedback text,moderation_status text default 'published',unique(project_id,author_id));
create table public.favorites(client_id uuid references profiles(id),talent_id uuid references profiles(id),created_at timestamptz default now(),primary key(client_id,talent_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),profile_id uuid not null references profiles(id),category text not null,title text not null,body text not null,data jsonb default '{}',read_at timestamptz,created_at timestamptz default now());
